package main

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"unicode/utf8"
)

// materialSymbols is every Material Symbols (Outlined) icon name, generated by material-symbols.sh
// from the font's published codepoints; lines starting with # say where it came from.
//
//go:embed material-symbols-outlined.txt
var materialSymbolsFile string

var materialSymbols = func() map[string]bool {
	names := map[string]bool{}
	for _, line := range strings.Split(materialSymbolsFile, "\n") {
		if line = strings.TrimSpace(line); line != "" && !strings.HasPrefix(line, "#") {
			names[line] = true
		}
	}
	return names
}()

// monitorActions are the actions a monitor hint may name.
var monitorActions = map[string]bool{"created": true, "changed": true, "deleted": true}

// labelPlaceholder is a {field} in a monitor label.
var labelPlaceholder = regexp.MustCompile(`\{([^{}]*)\}`)

// maxLabel is the most characters a monitor label may have as written.
const maxLabel = 120

type eventField struct {
	Name string `json:"name"`
	Kind string `json:"kind"`
}

type eventDecl struct {
	Type    string          `json:"type"`
	Fields  []eventField    `json:"fields"`
	Monitor json.RawMessage `json:"monitor"`
}

type monitorHint struct {
	Icon   *string `json:"icon"`
	IconBy *struct {
		Field string            `json:"field"`
		Icons map[string]string `json:"icons"`
	} `json:"iconBy"`
	Action      *string `json:"action"`
	ActionField *string `json:"actionField"`
	Label       *string `json:"label"`
}

// checkEvents checks the optional monitor hint on each of a plugin's events.publishes, refusing what
// the Host will refuse. Each problem names the plugin, the event type and the field; no monitor is
// valid.
func checkEvents(plugin string, events json.RawMessage) []string {
	if t := bytes.TrimSpace(events); len(t) == 0 || string(t) == "null" {
		return nil
	}
	var e struct {
		Publishes []eventDecl `json:"publishes"`
	}
	if err := json.Unmarshal(events, &e); err != nil {
		return []string{fmt.Sprintf("plugin %s events: %v", plugin, err)}
	}
	var problems []string
	for _, ev := range e.Publishes {
		problems = append(problems, checkMonitor(plugin, ev)...)
	}
	return problems
}

func checkMonitor(plugin string, ev eventDecl) []string {
	if t := bytes.TrimSpace(ev.Monitor); len(t) == 0 || string(t) == "null" {
		return nil
	}
	var problems []string
	fail := func(field, format string, args ...any) {
		problems = append(problems, fmt.Sprintf("plugin %s event %s: monitor.%s: %s", plugin, ev.Type, field, fmt.Sprintf(format, args...)))
	}
	var m monitorHint
	if err := json.Unmarshal(ev.Monitor, &m); err != nil {
		problems = append(problems, fmt.Sprintf("plugin %s event %s: monitor: %v", plugin, ev.Type, err))
		return problems
	}
	kinds := map[string]string{}
	for _, f := range ev.Fields {
		kinds[f.Name] = f.Kind
	}
	stringField := func(field, name string) {
		if kinds[name] != "string" {
			fail(field, "%q is not a declared string field of the event", name)
		}
	}

	switch {
	case m.Icon == nil:
		fail("icon", "is required")
	case !materialSymbols[*m.Icon]:
		fail("icon", "%q is not a Material Symbols (Outlined) icon name", *m.Icon)
	}
	if m.IconBy != nil {
		stringField("iconBy.field", m.IconBy.Field)
		values := make([]string, 0, len(m.IconBy.Icons))
		for value := range m.IconBy.Icons {
			values = append(values, value)
		}
		sort.Strings(values)
		for _, value := range values {
			if icon := m.IconBy.Icons[value]; !materialSymbols[icon] {
				fail("iconBy.icons."+value, "%q is not a Material Symbols (Outlined) icon name", icon)
			}
		}
	}
	switch {
	case m.Action != nil && m.ActionField != nil:
		fail("action", "give action or actionField, not both")
	case m.Action == nil && m.ActionField == nil:
		fail("action", "give action (created, changed or deleted) or actionField")
	case m.Action != nil && !monitorActions[*m.Action]:
		fail("action", "%q is not created, changed or deleted", *m.Action)
	case m.ActionField != nil:
		stringField("actionField", *m.ActionField)
	}
	if m.Label != nil {
		if n := utf8.RuneCountInString(*m.Label); n > maxLabel {
			fail("label", "is %d characters; at most %d", n, maxLabel)
		}
		for _, p := range labelPlaceholder.FindAllStringSubmatch(*m.Label, -1) {
			if k := kinds[p[1]]; k != "string" && k != "number" {
				fail("label", "{%s} is not a declared string or number field of the event", p[1])
			}
		}
	}
	return problems
}
